import{_ as n,a,c as o,ac as t}from"./chunks/framework.BSuaGltH.js";const h=JSON.parse('{"title":"第二册：实践与进步 · 单元 4 语法总结 · 动词、宾语与补足语至非真实条件句","description":"L73–L96 规则、例句、易错点。","frontmatter":{"title":"第二册：实践与进步 · 单元 4 语法总结 · 动词、宾语与补足语至非真实条件句","description":"L73–L96 规则、例句、易错点。","splitFrom":"life/english/new-concept/book-2/unit-04/grammar.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"句法与表达查阅","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第二册：实践与进步 · 单元 4 语法总结","summary":"L73–L96 规则、例句、易错点。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · 单元 4 语法总结 · 时间、原因与让步从句至将来进行时与过程","link":"/life/english/new-concept/book-2/unit-04/grammar-part-02"},"next":{"text":"第二册：实践与进步 · 单元 4 单词与短语","link":"/life/english/new-concept/book-2/unit-04/vocabulary"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · 单元 4 语法总结 · 时间、原因与让步从句至将来进行时与过程","link":"/life/english/new-concept/book-2/unit-04/grammar-part-02"},"next":{"text":"第二册：实践与进步 · 单元 4 单词与短语","link":"/life/english/new-concept/book-2/unit-04/vocabulary"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-04/grammar-part-03.md","filePath":"life/english/new-concept/book-2/unit-04/grammar-part-03.md"}'),i={name:"life/english/new-concept/book-2/unit-04/grammar-part-03.md"};function r(l,e,s,p,c,g){return a(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="第二册-实践与进步-·-单元-4-语法总结-·-动词、宾语与补足语至非真实条件句" tabindex="-1">第二册：实践与进步 · 单元 4 语法总结 · 动词、宾语与补足语至非真实条件句 <a class="header-anchor" href="#第二册-实践与进步-·-单元-4-语法总结-·-动词、宾语与补足语至非真实条件句" aria-label="Permalink to &quot;第二册：实践与进步 · 单元 4 语法总结 · 动词、宾语与补足语至非真实条件句&quot;">​</a></h1><p><a href="/life/english/new-concept/book-2/unit-04/grammar">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-2/unit-04/overview">单元导读</a> · <a href="/life/english/new-concept/book-2/unit-04/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-2/unit-04/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-2/unit-04/review">单元复习与自测</a></p><h2 id="动词、宾语与补足语" tabindex="-1">动词、宾语与补足语 <a class="header-anchor" href="#动词、宾语与补足语" aria-label="Permalink to &quot;动词、宾语与补足语 {#动词、宾语与补足语}&quot;">​</a></h2><p>英语陈述句通常先交代主语和谓语，再放宾语及必要的补足语。部分动词可以带人和物两个宾语，如 give somebody something，也可改为 give something to somebody；buy 常用 for。并不是所有动词都支持这两种结构，explain 通常用 explain something to somebody。补足语则进一步说明宾语的身份或状态，不能与表示地点和时间的附加信息混为一谈。本课应用：meant to say 表原本想说，meant saying 在此不表达说话意图。mean doing 常表示“意味着做某事”，需要另一语境。</p><p><strong>L89 原创例句：</strong> I meant to say Thursday, but I accidentally said Tuesday.</p><p>我本想说周四，却不小心说成了周二。</p><p><strong>易错：</strong> Thursday 与 Tuesday 不是同一天；不能只因都以 T 开头而在时间安排中混用。</p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-089">Lesson 89</a></p><h2 id="过去进行时与叙事背景" tabindex="-1">过去进行时与叙事背景 <a class="header-anchor" href="#过去进行时与叙事背景" aria-label="Permalink to &quot;过去进行时与叙事背景 {#过去进行时与叙事背景}&quot;">​</a></h2><p>过去进行时由 was/were 加动词 -ing 构成，描述过去某个时刻正在展开的活动。它常与一般过去时配合：进行时给出背景，过去式指出发生在背景中的事件。when 与 while 的选择取决于从句表达瞬间还是过程，不能把两者当作机械的时态开关。两个同时持续的活动也可都用进行时，而状态动词往往仍用简单时态。本课应用：were drifting 描述风中持续漂移，noticed 是其中发生的发现。漂移方向可以改变，单句不保证最终抵达观察到的田地。</p><p><strong>L91 原创例句：</strong> We were drifting over the fields when the pilot noticed a clear landing area.</p><p>我们正飘过田野时，飞行员发现了一块空旷的降落区。</p><p><strong>易错：</strong> over the fields 是在田野上方；through the fields 通常表示从田地内部穿行。</p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-091">Lesson 91</a></p><h2 id="一般现在时与习惯" tabindex="-1">一般现在时与习惯 <a class="header-anchor" href="#一般现在时与习惯" aria-label="Permalink to &quot;一般现在时与习惯 {#一般现在时与习惯}&quot;">​</a></h2><p>一般现在时可以描述习惯、规律和当前相对稳定的状态。第三人称单数主语的实义动词通常加 -s；使用 does 或 does not 后，动词回到原形。频率副词常放在实义动词前、be 动词后，但句首句尾也有特定用法。正在发生的临时动作通常另用进行时，不能仅因句中出现 today 就自动选一般现在时或现在进行时。本课应用：learn to float 表获得一种能力，practise floating 表练习已经开始做的动作。描述训练规律用一般现在时，不把练习次数直接当作成绩保证。</p><p><strong>L94 原创例句：</strong> The children practise floating before they learn to swim across the pool.</p><p>孩子们先练习漂浮，再学横穿泳池。</p><p><strong>易错：</strong> practise to float 应改为 practise floating；learn floating 并非此处常用搭配。</p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-094">Lesson 94</a></p><h2 id="非真实条件句" tabindex="-1">非真实条件句 <a class="header-anchor" href="#非真实条件句" aria-label="Permalink to &quot;非真实条件句 {#非真实条件句}&quot;">​</a></h2><p>与现在事实不同或可能性较小的假设常用 if 加过去式，主句用 would/could 加原形；与过去事实相反则用 if 加 had done，主句用 would/could have done。这里的过去形式主要表达距离感，不总指过去时间。be 在正式假设中可用 were。选择句型前先确定假设发生的时间，再检查结果的时间，不要把真实未来条件与虚拟假设混用。本课应用：If people could ... would ... 表假设世界规则，不是现实技术声明。写幻想时先确定能力条件，再推导结果，避免条件和结果互相矛盾。</p><p><strong>L95 原创例句：</strong> If people could store sunlight in a pocket, winter evenings would look different.</p><p>如果人们能把阳光储存在口袋里，冬日夜晚就会大不相同。</p><p><strong>易错：</strong> would can store 错误；能力假设直接用 could，结果可用 would be able to。</p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-095">Lesson 95</a></p>',27)])])}const u=n(i,[["render",r]]);export{h as __pageData,u as default};
